  ('b336647f-f174-5571-a2d2-9a398367cd3b', null, (select id from public.skills where slug = 'write-g12-argument-writing'), null, 'medium',
   $q$Which choice would best replace sentences (9) and (10) as the conclusion?$q$, $q$[{"text":"The district should also build an indoor field house so that heat is never a problem.","is_correct":false,"misconception_token":"introduces-new-topic"},{"text":"Sports teach teamwork and discipline, and every student should try at least one.","is_correct":false,"misconception_token":"too-general"},{"text":"A single meter would let Orland Valley protect athletes on humid days that the current rule misses, while keeping more practices on the schedule.","is_correct":true},{"text":"Coaches who resist this change are putting trophies ahead of the health of their players.","is_correct":false,"misconception_token":"dismissive-tone"}]$q$::jsonb, $q$A single meter would let Orland Valley protect athletes on humid days that the current rule misses, while keeping more practices on the schedule.$q$, $q$The correct conclusion restates the claim and brings together both strands of the argument: better protection and fewer cancellations. Accusing coaches of misplaced priorities replaces reasoning with an attack.$q$, 'draft', '7f0cd155-6a0b-5ba4-a5c4-57de51c0cd9a')
